// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatIllegalArgumentException;

import org.junit.jupiter.api.Test;

class LmdbAdjacencyPredicateCatalogTest {

	@Test
	void appendedSegmentsPreserveEveryExistingOrdinal() {
		try (LmdbAdjacencyArena arena = new LmdbAdjacencyArena(4096)) {
			LmdbAdjacencyPredicateCatalog base = LmdbAdjacencyPredicateCatalog.base(arena, new long[] { 10, 100 });
			LmdbAdjacencyPredicateCatalog extended = base.extendAppend(new long[] { 5, 50, Long.MIN_VALUE });

			assertThat(extended.size()).isEqualTo(5);
			assertThat(extended.ordinalForRaw(10)).isZero();
			assertThat(extended.ordinalForRaw(100)).isEqualTo(1);
			assertThat(extended.ordinalForRaw(5)).isEqualTo(2);
			assertThat(extended.ordinalForRaw(50)).isEqualTo(3);
			assertThat(extended.ordinalForRaw(Long.MIN_VALUE)).isEqualTo(4);
			assertThat(extended.rawForOrdinal(2)).isEqualTo(5);
			assertThat(extended.sortedRawIdsCopy()).containsExactly(10, 100, 5, 50, Long.MIN_VALUE);

			assertThat(base.size()).isEqualTo(2);
			assertThat(base.ordinalForRaw(5)).isEqualTo(-1);
			assertThat(extended.modeledJavaBytes()).isGreaterThan(base.modeledJavaBytes());
		}
	}

	@Test
	void appendedSegmentsRejectDuplicatesAndUnsignedDisorder() {
		try (LmdbAdjacencyArena arena = new LmdbAdjacencyArena(4096)) {
			LmdbAdjacencyPredicateCatalog base = LmdbAdjacencyPredicateCatalog.base(arena, new long[] { 10, 100 });

			assertThatIllegalArgumentException().isThrownBy(() -> base.extendAppend(new long[] { 10 }));
			assertThatIllegalArgumentException().isThrownBy(() -> base.extendAppend(new long[] { 50, 5 }));
			assertThatIllegalArgumentException().isThrownBy(() -> base.extendAppend(new long[] { 50, 50 }));
		}
	}
}
